body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text-color, #e2e8f0);
  margin: 0;
  padding: 12px;
  background: transparent;
  box-sizing: border-box;
}
.pomo-widget {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  height: 100%;
  gap: 8px;
}
.pomo-modes {
  display: flex;
  gap: 4px;
  background: rgba(255, 255, 255, 0.06);
  padding: 3px;
  border-radius: 8px;
}
.widget.light .pomo-modes {
  background: rgba(0, 0, 0, 0.05);
}
.pomo-mode {
  background: transparent;
  border: none;
  color: inherit;
  font-size: 0.75rem;
  padding: 4px 10px;
  border-radius: 6px;
  cursor: pointer;
  opacity: 0.7;
  transition: all 0.2s;
}
.pomo-mode.active {
  background: #f43f5e;
  color: #fff;
  opacity: 1;
  font-weight: 600;
}
.pomo-display {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.pomo-time {
  font-size: 2.8rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -1px;
}
.pomo-session {
  font-size: 0.75rem;
  opacity: 0.65;
}
.pomo-controls {
  display: flex;
  gap: 8px;
}
.pomo-btn {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: inherit;
  padding: 6px 18px;
  border-radius: 6px;
  font-size: 0.82rem;
  cursor: pointer;
  transition: all 0.2s;
}
.widget.light .pomo-btn {
  background: rgba(0, 0, 0, 0.06);
  border-color: rgba(0, 0, 0, 0.12);
}
.pomo-btn.primary {
  background: #f43f5e;
  border-color: #f43f5e;
  color: #fff;
  font-weight: 600;
}
.pomo-btn:hover { opacity: 0.9; }

js:
(function() {
  let timeLeft = 1500;
  let totalTime = 1500;
  let timerId = null;
  let sessions = 1;

  const timeEl = document.getElementById('pomo-time');
  const sessionEl = document.getElementById('pomo-session');
  const toggleBtn = document.getElementById('pomo-toggle');
  const resetBtn = document.getElementById('pomo-reset');
  const modes = document.querySelectorAll('.pomo-mode');

  function playChime() {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = 'sine';
      osc.frequency.setValueAtTime(587.33, ctx.currentTime); // D5
      osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.3); // A5
      gain.gain.setValueAtTime(0.3, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);
      osc.start();
      osc.stop(ctx.currentTime + 0.5);
    } catch(e) {}
  }

  function formatTime(sec) {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  }

  function updateDisplay() {
    timeEl.textContent = formatTime(timeLeft);
  }

  function startTimer() {
    if (timerId) return;
    toggleBtn.textContent = 'Pause';
    timerId = setInterval(() => {
      timeLeft--;
      updateDisplay();
      if (timeLeft <= 0) {
        clearInterval(timerId);
        timerId = null;
        toggleBtn.textContent = 'Start';
        playChime();
        if (window.widget && window.widget.notifications) {
          window.widget.notifications.show('Pomodoro Complete!', { body: 'Time to take a break or start next session.' });
        }
        sessions++;
        sessionEl.textContent = `Session ${sessions} of 4`;
      }
    }, 1000);
  }

  function pauseTimer() {
    if (!timerId) return;
    clearInterval(timerId);
    timerId = null;
    toggleBtn.textContent = 'Start';
  }

  toggleBtn.addEventListener('click', () => {
    if (timerId) pauseTimer();
    else startTimer();
  });

  resetBtn.addEventListener('click', () => {
    pauseTimer();
    timeLeft = totalTime;
    updateDisplay();
  });

  modes.forEach(btn => {
    btn.addEventListener('click', () => {
      modes.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      pauseTimer();
      totalTime = parseInt(btn.getAttribute('data-time'), 10);
      timeLeft = totalTime;
      updateDisplay();
    });
  });

  updateDisplay();

  if (window.widget && window.widget.registerCommand) {
    window.widget.registerCommand('pomodoro', {
      description: 'Control Pomodoro timer [start|pause|reset]',
      usage: 'pomodoro [start|pause|reset]',
      category: 'Productivity',
      execute: (args) => {
        const cmd = (args && args[0]) ? args[0].toLowerCase() : '';
        if (cmd === 'start') { startTimer(); return 'Pomodoro started'; }
        if (cmd === 'pause') { pauseTimer(); return 'Pomodoro paused'; }
        if (cmd === 'reset') { pauseTimer(); timeLeft = totalTime; updateDisplay(); return 'Pomodoro reset'; }
        return `Pomodoro: ${formatTime(timeLeft)} (${timerId ? 'running' : 'paused'})`;
      }
    });
  }
})();
